<script setup lang="ts">
import { computed, shallowRef } from 'vue'
import { useI18n } from 'vue-i18n'
import Select from '@/components/common/Select.vue'
import KiloStatusBadge from './KiloStatusBadge.vue'
import { kiloVerificationUrl } from '@/api/admin/kilo'
import type { KiloJob, KiloSubscriptionRecoveryAction } from '@/api/admin/kilo'

const props = defineProps<{ items: KiloJob[]; busyId: number | null; disabled: boolean }>()
const emit = defineEmits<{ retry: [job: KiloJob]; cancel: [job: KiloJob]; delete: [job: KiloJob]; changeProxy: [job: KiloJob]; recoverSubscription: [job: KiloJob, action: KiloSubscriptionRecoveryAction] }>()
const { t, te, locale } = useI18n()
const status = shallowRef('all')
const page = shallowRef(1)
const pageSize = 20
const filtered = computed(() => props.items.filter(item => status.value === 'all' || item.status === status.value).sort((a, b) => b.id - a.id))
const pageCount = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize)))
const currentPage = computed(() => Math.min(page.value, pageCount.value))
const visible = computed(() => filtered.value.slice((currentPage.value - 1) * pageSize, currentPage.value * pageSize).map(job => ({ ...job, verificationUrl: kiloVerificationUrl(job.verification_url), displayTitle: job.prepared_name || job.source_name || t('kilo.jobs.onboardingTitle', { id: job.source_account_id ?? job.id }) })))
const options = computed(() => [{ value: 'all', label: t('common.all') }, ...[...new Set(props.items.map(item => item.status))].map(value => ({ value, label: te(`kilo.status.${value}`) ? t(`kilo.status.${value}`) : t('kilo.status.unknown') }))])
function stageLabel(value: string) { return te(`kilo.stages.${value}`) ? t(`kilo.stages.${value}`) : value || t('kilo.stages.processing') }
function factLabel(value?: boolean) { return t(value === undefined ? 'kilo.jobs.factUnknown' : value ? 'kilo.jobs.factReady' : 'kilo.jobs.factPending') }
function factTone(value?: boolean) { return value === true ? 'text-emerald-700 dark:text-emerald-300' : 'text-gray-500 dark:text-dark-400' }
function canRetry(job: KiloJob) { return job.recovery_actions?.includes('retry') === true }
function canRecover(job: KiloJob, action: KiloSubscriptionRecoveryAction) { return job.status === 'failed' && Number.isSafeInteger(job.revision) && job.revision > 0 && job.recovery_actions?.includes(action) === true }
function canManageFailure(job: KiloJob) { return ['failed', 'cancelled', 'canceled'].includes(job.status) }
function canCancel(job: KiloJob) { return !job.finished_at && ['queued', 'pending', 'running', 'binding', 'awaiting_authorization', 'verifying', 'needs_action', 'waiting'].includes(job.status) }
function formatDate(value: string) { return new Date(value).toLocaleString(locale.value) }
</script>

<template>
  <section class="space-y-4" :aria-label="t('kilo.jobs.title')">
    <div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><p class="max-w-2xl text-sm leading-6 text-gray-600 dark:text-dark-300">{{ t('kilo.jobs.description') }}</p><div class="w-full shrink-0 sm:w-48"><Select id="kilo-job-filter" v-model="status" :options="options" :aria-label="t('kilo.jobs.filter')" @change="page = 1" /></div></div>
    <p v-if="!visible.length" class="rounded-xl border border-dashed border-gray-200 px-4 py-12 text-center text-sm text-gray-500 dark:border-dark-700 dark:text-dark-400">{{ items.length ? t('kilo.prepared.noMatches') : t('kilo.jobs.empty') }}</p>
    <ol class="space-y-3"><li v-for="job in visible" :key="job.id" class="rounded-xl border border-gray-200 p-4 dark:border-dark-700">
      <div class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><h3 class="break-words text-sm font-semibold text-gray-900 dark:text-dark-100">{{ job.displayTitle }} <span class="font-normal text-gray-400">#{{ job.id }}</span></h3><p class="mt-1 break-all text-xs text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.batchId', { id: job.batch_id }) }}</p><p class="mt-1 text-xs text-gray-500 dark:text-dark-400">{{ formatDate(job.created_at) }}</p></div><KiloStatusBadge :status="job.status" /></div>
      <dl class="mt-4 grid gap-3 text-sm sm:grid-cols-3"><div><dt class="text-xs text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.mode') }}</dt><dd class="mt-1">{{ job.job_kind === 'onboard_source' ? t('kilo.jobs.onboardingMode') : job.source_account_id ? t('kilo.jobs.subscriptionMode') : t('kilo.jobs.activationMode') }}</dd></div><div><dt class="text-xs text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.source') }}</dt><dd class="mt-1 break-words">{{ job.source_account_id ? t('kilo.jobs.sourceIdentity', { name: job.source_name, id: job.source_account_id }) : t('kilo.jobs.noSource') }}</dd></div><div><dt class="text-xs text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.stage') }}</dt><dd class="mt-1">{{ stageLabel(job.stage) }}</dd></div></dl>
      <div v-if="job.status === 'awaiting_authorization'" class="mt-4 space-y-3 rounded-lg bg-amber-50 p-3 dark:bg-amber-900/20"><p class="text-sm leading-6 text-amber-800 dark:text-amber-300">{{ job.job_kind === 'onboard_source' ? t('kilo.jobs.onboardingAuthorize') : t('kilo.jobs.authorize', { kilo: job.prepared_name, source: job.source_name || `#${job.source_account_id}` }) }}</p><p class="text-xs leading-5 text-amber-800 dark:text-amber-300">{{ t('kilo.jobs.remoteVerification') }}</p><p v-if="job.user_code" class="select-all break-all font-mono text-lg" translate="no">{{ job.user_code }}</p><a v-if="job.verificationUrl" :href="job.verificationUrl" target="_blank" rel="noopener noreferrer" class="btn btn-primary btn-sm inline-flex">{{ t('kilo.jobs.openAuthorization') }}</a><p v-else class="text-xs text-amber-800 dark:text-amber-300">{{ t('kilo.jobs.awaitLink') }}</p></div>
      <dl v-if="job.job_kind === 'onboard_source'" class="mt-3 grid gap-3 text-sm sm:grid-cols-3"><div><dt class="text-xs text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.gateway') }}</dt><dd class="mt-1">{{ job.account_id ? t('kilo.prepared.managedId', { id: job.account_id }) : t('kilo.jobs.gatewayPending') }}<span v-if="job.prepared_id === null" class="mt-1 block text-xs text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.credentialPending') }}</span></dd></div><div><dt class="text-xs text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.scope') }}</dt><dd class="mt-1 break-all">{{ t(`kilo.workspaceMode.${job.workspace_mode || 'auto'}`) }}<span v-if="job.organization_id" class="mt-1 block text-xs text-gray-500 dark:text-dark-400">{{ t('kilo.prepared.organization', { id: job.organization_id }) }}</span></dd></div><div><dt class="text-xs text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.loginProxy') }}</dt><dd class="mt-1">{{ job.login_proxy_id ? t('kilo.jobs.loginProxyValue', { id: job.login_proxy_id }) : t('common.notAvailable') }}</dd></div></dl>
      <section v-if="job.job_kind === 'onboard_source'" class="mt-4 rounded-lg bg-gray-50 p-3 dark:bg-dark-900/50" :aria-label="t('kilo.jobs.facts')"><dl class="grid gap-3 text-xs sm:grid-cols-3"><div><dt class="text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.credentialFact') }}</dt><dd class="mt-1 font-medium" :class="factTone(job.credential_ready)">{{ factLabel(job.credential_ready) }}</dd></div><div><dt class="text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.subscriptionFact') }}</dt><dd class="mt-1 font-medium" :class="factTone(job.subscription_connected)">{{ factLabel(job.subscription_connected) }}</dd></div><div><dt class="text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.quotaFact') }}</dt><dd class="mt-1 font-medium" :class="factTone(job.quota_oauth_ready)">{{ factLabel(job.quota_oauth_ready) }}</dd></div></dl><p class="mt-3 text-xs leading-5 text-gray-500 dark:text-dark-400">{{ t('kilo.jobs.quotaBoundary') }}</p></section>
      <div v-if="job.last_error || job.error_code || job.failed_stage" class="mt-3 space-y-2 break-words rounded-lg bg-red-50 p-3 text-sm leading-6 text-red-700 dark:bg-red-900/20 dark:text-red-300"><p v-if="job.last_error">{{ job.last_error }}</p><p v-if="job.error_code" class="break-all font-mono text-xs">{{ t('kilo.jobs.errorCode') }}: {{ job.error_code }}</p><p v-if="job.failed_stage" class="text-xs">{{ t('kilo.jobs.failedStage') }}: {{ stageLabel(job.failed_stage) }}</p></div>
      <div v-if="job.next_action || job.next_attempt_at" class="mt-3 space-y-2 rounded-lg bg-amber-50 p-3 text-sm leading-6 text-amber-800 dark:bg-amber-900/20 dark:text-amber-300"><p v-if="job.next_action" class="break-words"><span class="font-medium">{{ t('kilo.jobs.nextAction') }}: </span>{{ job.next_action }}</p><p v-if="job.next_attempt_at" class="text-xs">{{ t('kilo.jobs.nextAttempt', { time: formatDate(job.next_attempt_at) }) }}</p></div>
      <p v-if="job.account_id && ['bound', 'completed', 'succeeded'].includes(job.status)" class="mt-3 text-sm text-emerald-700 dark:text-emerald-300">{{ t(job.job_kind === 'onboard_source' ? job.stage === 'bound' ? 'kilo.jobs.onboardingCompleted' : 'kilo.jobs.onboardingFinished' : 'kilo.jobs.completed', { id: job.account_id }) }}</p>
      <div v-if="canRetry(job) || canCancel(job) || canManageFailure(job)" class="mt-4 flex flex-wrap gap-2"><button v-if="canRetry(job)" type="button" class="btn btn-secondary btn-sm" :disabled="disabled || busyId !== null" @click="emit('retry', job)">{{ busyId === job.id ? t('common.processing') : t('kilo.jobs.retry') }}</button><button v-if="canRecover(job, 'reconcile_subscription')" type="button" class="btn btn-secondary btn-sm" :disabled="disabled || busyId !== null" data-testid="kilo-job-reconcile-subscription" @click="emit('recoverSubscription', job, 'reconcile_subscription')">{{ t('kilo.jobs.recovery.reconcile') }}</button><button v-if="canRecover(job, 'reauthorize_subscription')" type="button" class="btn btn-secondary btn-sm text-amber-700 dark:text-amber-300" :disabled="disabled || busyId !== null" data-testid="kilo-job-reauthorize-subscription" @click="emit('recoverSubscription', job, 'reauthorize_subscription')">{{ t('kilo.jobs.recovery.reauthorize') }}</button><button v-if="canManageFailure(job) && job.job_kind === 'onboard_source'" type="button" class="btn btn-secondary btn-sm" :disabled="disabled || busyId !== null" data-testid="kilo-job-change-proxy" @click="emit('changeProxy', job)">{{ t('kilo.jobs.changeProxy') }}</button><button v-if="canCancel(job)" type="button" class="btn btn-secondary btn-sm text-red-600 dark:text-red-400" :disabled="disabled || busyId !== null" @click="emit('cancel', job)">{{ busyId === job.id ? t('common.processing') : t('kilo.jobs.cancel') }}</button><button v-if="canManageFailure(job)" type="button" class="btn btn-secondary btn-sm text-red-600 dark:text-red-400" :disabled="disabled || busyId !== null" data-testid="kilo-job-delete" @click="emit('delete', job)">{{ t('kilo.jobs.delete') }}</button></div>
    </li></ol>
    <div v-if="filtered.length" class="flex flex-wrap items-center justify-between gap-3 text-xs text-gray-500 dark:text-dark-400"><span>{{ t('kilo.pagination', { page: currentPage, pages: pageCount, count: filtered.length }) }}</span><div class="flex gap-2"><button type="button" class="btn btn-secondary btn-sm" :disabled="currentPage <= 1" @click="page = currentPage - 1">{{ t('common.back') }}</button><button type="button" class="btn btn-secondary btn-sm" :disabled="currentPage >= pageCount" @click="page = currentPage + 1">{{ t('common.next') }}</button></div></div>
  </section>
</template>
